local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)

local ServiceMaker = {}
ServiceMaker.__index = ServiceMaker

local _order = 0

function ServiceMaker.new(descriptor: ServiceDescriptor)
	local self = setmetatable({}, ServiceMaker)
	self._descriptor = descriptor
	self:_updateOrder()
	self._interface = descriptor.ServiceType
	self._implementation = descriptor.ImplementationType
	self.Handler = function(lifetime, a, b, c)
		if descriptor.ImplementationInstance then
			return descriptor.ImplementationInstance
		end
		if descriptor.ImplementationFactory then
			return descriptor.ImplementationFactory(lifetime)
		end
		return self:SolveNoCache(lifetime, a, b, c)
	end
	self._originalFuncHandler = self.Handler
	self.LifeTime = ServiceLifetime.Transient
	return self
end

function ServiceMaker:_updateOrder()
	_order = _order + 1
	self.Order = _order
end

function ServiceMaker:AsSingleton()
	error("Not implemented")
end

function ServiceMaker:PerScope()
	error("Not implemented")
end

function ServiceMaker:SolveNoCacheWithFuncHandler(lifeTime, unsolved, service, enumOrder)
	if not self._implementation then
		return self._originalFuncHandler(lifeTime, unsolved, service, enumOrder)
	end
	return self:SolveNoCache(lifeTime, unsolved, service, enumOrder)
end

function ServiceMaker:SolveNoCache(lifeTime, unsolved, service, enumOrder)
	return self:_SolveNoCache(lifeTime, unsolved, service)
end

function ServiceMaker:_SolveNoCache(lifeTime, unsolved, service)
	local constructors = nil
	local isEnumerableGeneric = false
	if self._implementation.IsGenericType then
		local genericArgs = service:GetGenericArguments()

		local tmp = genericArgs[1]:GetGenericArguments()
		if #tmp > 0 then
			isEnumerableGeneric = true
			genericArgs = tmp
		end

		if self._implementation.IsGenericTypeDefinition then
			local newType = self._implementation:MakeGenericType(genericArgs)
			constructors = newType:GetConstructors()
		else
			constructors = self._implementation:GetConstructors()
		end
	else
		constructors = self._implementation:GetConstructors()
	end

	if #constructors == 0 then
		error("not impl")
		--constructors = self._implementation:GetConstructors(BindingFlags.Instance + BindingFlags.NonPublic)
	end

	local constructor = constructors[1]

	local args = nil
	if constructor then
		local constructorParams = constructor:GetParameters()
		args = {}
		for _, param in ipairs(constructorParams) do
			unsolved = self:_updateUnsolvedService(unsolved, service)
			if table.contains(unsolved, param.ParameterType) then
				error({ type = "CircularDependencyException", Services = { param.ParameterType.FullName } })
			end

			local resolved = lifeTime:GetService(unsolved, param.ParameterType)

			if not resolved then
				error(
					string.format(
						"Unable to resolve service for type '%s' while attempting to activate '%s'",
						param.ParameterType.FullName,
						self._implementation
					)
				)
			end

			table.remove(unsolved, table.indexOf(unsolved, service))

			table.insert(args, resolved)
		end
	end

	if not self._interface.IsGenericTypeDefinition then
		return self:_resolveNormal(args)
	else
		return self:_resolveGeneric(service, args, isEnumerableGeneric)
	end
end

function ServiceMaker:_updateUnsolvedService(unsolved, service)
	if not unsolved then
		unsolved = {}
	end

	if not table.contains(unsolved, service) then
		table.insert(unsolved, service)
	end
	return unsolved
end

function ServiceMaker:_resolveNormal(args)
	return self._implementation.new(table.unpack(args))
end

function ServiceMaker:_resolveGeneric(service, args, isEnumerableGeneric)
	local tArgs = service:GetGenericArguments()

	local genericType
	if isEnumerableGeneric then
		genericType = self._implementation:MakeGenericType(tArgs[1]:GetGenericArguments())
	else
		genericType = self._implementation:MakeGenericType(tArgs)
	end

	return genericType.new(table.unpack(args))
end

return ServiceMaker
